declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    AtExit : BOOL;
    Jam : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Belt : BOOL := FALSE;
    Complete : BOOL := FALSE;
    Fault : BOOL := FALSE;
END_VAR
VAR
State : USINT := 0;
END_VAR

implementation:
IF Jam THEN State := 3;
ELSIF Reset THEN State := 0;
ELSIF State = 3 THEN
    State := 3;
ELSIF Stop THEN State := 0;
ELSE
    CASE State OF
        0: IF Start AND NOT AtExit THEN State := 1; END_IF;
        1: IF AtExit THEN State := 2; END_IF;
    END_CASE;
END_IF;
Belt := State = 1;
Complete := State = 2;
Fault := State = 3;
